// Parses the .debug_macro section of a file with DWARF debug info (version 5+) and 
// prints the result to the ghidra console.
// @category DWARF



using ghidra.app.script;
using ghidra.app.util.bin.format.dwarf;
using ghidra.app.util.bin.format.dwarf.macro;
using ghidra.app.util.bin.format.dwarf.macro.entry;
using ghidra.app.util.bin.format.dwarf.sectionprovider;
using ghidra.app.util.bin.format.dwarf.sectionprovider;

public class DWARFMacroScript : GhidraScript {

	/* @Override */
	protected void run()
    {
		DWARFSectionProvider dsp =
			DWARFSectionProviderFactory.createSectionProviderFor(currentProgram, monitor);
		if (dsp == null) {
			printerr("Unable to find DWARF information");
			return;
		}

		using (DWARFProgram dprog = new DWARFProgram(currentProgram, new DWARFImportOptions(), dsp))
{
			dprog.init(monitor);
			foreach (DWARFCompilationUnit cu in dprog.getCompilationUnits()) {
				dumpMacros(cu.getMacros(), 0);
			}
		}
	}

	void dumpMacros(DWARFMacroHeader macroHeader, int indent)
    {
		foreach (DWARFMacroInfoEntry macroEntry in macroHeader.getEntries()) {
			print(macroEntry.toString().indent(indent));
			switch (macroEntry) {
				case DWARFMacroImport macroImport:
					dumpMacros(macroImport.getImportedMacroHeader(), indent + 2);
					break;
				case DWARFMacroStartFile macroStartFile:
					indent += 2;
					break;
				case DWARFMacroEndFile macroEndFile:
					indent -= 2;
					break;
				default:
			}
		}
	}

}
